import hashlib, hmac, json, random

random.seed(7)

# --- A fake, flaky customer API -------------------------------------------
processed = {}
def fake_api(method, path, body=None, idempotency_key=None):
    if random.random() < 0.4:
        return 503, {"error": "temporarily unavailable"}
    if idempotency_key in processed:
        return 200, processed[idempotency_key]          # same result, no double payment
    result = {"payment_id": f"pay_{len(processed) + 1}", "amount": body["amount"]}
    processed[idempotency_key] = result
    return 201, result

# --- Our client: retry with exponential backoff + jitter -------------------
def call(method, path, body, key, max_attempts=6, base=0.5):
    for attempt in range(1, max_attempts + 1):
        status, data = fake_api(method, path, body, idempotency_key=key)
        if status < 300:
            return status, data, attempt
        if 400 <= status < 500 and status != 429:
            raise ValueError(f"Client error {status}: fix the request")
        wait = base * 2 ** (attempt - 1) * random.uniform(0.5, 1.5)
        print(f"  attempt {attempt}: {status}, would wait {wait:.2f}s")
    raise RuntimeError("gave up")

status, data, n = call("POST", "/payments", {"amount": 1200}, key="claim-C-001")
print(f"Paid on attempt {n}: {data}")
status, data, n = call("POST", "/payments", {"amount": 1200}, key="claim-C-001")
print(f"Retried same key -> {data}  (payments made: {len(processed)})")

# --- Verifying a webhook signature -----------------------------------------
secret = b"shared-webhook-secret"
payload = json.dumps({"event": "claim.closed", "id": "C-001"}).encode()
sent_sig = hmac.new(secret, payload, hashlib.sha256).hexdigest()

def verify(body, signature):
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

print("\nGenuine webhook valid?  ", verify(payload, sent_sig))
print("Tampered webhook valid? ", verify(payload.replace(b"C-001", b"C-999"), sent_sig))

# Find when errors started and what changed just before.
import json
from collections import Counter

log_lines = """
{"t": "09:00", "level": "info",  "event": "request", "status": 200}
{"t": "09:01", "level": "info",  "event": "request", "status": 200}
{"t": "09:02", "level": "info",  "event": "deploy",  "version": "v1.8.0"}
{"t": "09:02", "level": "info",  "event": "request", "status": 200}
{"t": "09:03", "level": "info",  "event": "config",  "change": "CRM_API_URL updated"}
{"t": "09:03", "level": "error", "event": "request", "status": 502, "upstream": "crm"}
{"t": "09:04", "level": "error", "event": "request", "status": 502, "upstream": "crm"}
{"t": "09:04", "level": "info",  "event": "request", "status": 200}
{"t": "09:05", "level": "error", "event": "request", "status": 502, "upstream": "crm"}
"""
events = [json.loads(l) for l in log_lines.strip().splitlines()]

per_minute = Counter()
totals = Counter()
for e in events:
    if e["event"] == "request":
        totals[e["t"]] += 1
        per_minute[e["t"]] += e["status"] >= 500
print("minute  errors/requests")
for t in sorted(totals):
    print(f"{t}   {per_minute[t]}/{totals[t]}  {'!' * per_minute[t]}")

first_error = next(e for e in events if e["level"] == "error")
changes = [e for e in events if e["event"] in ("deploy", "config") and e["t"] <= first_error["t"]]
print(f"\nFirst error at {first_error['t']} (upstream: {first_error['upstream']})")
print("Changes before it, most recent first:")
for c in reversed(changes):
    print("  ", c["t"], c["event"], c.get("version") or c.get("change"))
print("\nPrime suspect: the CRM URL config change, since errors all come from the crm upstream.")
